create table if not exists public.consultation_dashboard_settings(id integer primary key default 1 check(id=1),welcome_title text not null default '',welcome_title_en text not null default '',welcome_text text not null default '',welcome_text_en text not null default '',status_label text not null default '',status_label_en text not null default '',default_dietitian_name text not null default '',default_dietitian_role text not null default '',default_dietitian_role_en text not null default '',default_dietitian_image text not null default '',ai_title text not null default '',ai_title_en text not null default '',ai_questions jsonb not null default '[]',ai_questions_en jsonb not null default '[]',quick_actions jsonb not null default '[]',updated_at timestamptz not null default now());
alter table public.consultation_dashboard_settings enable row level security;
drop policy if exists "Public reads consultation dashboard" on public.consultation_dashboard_settings;drop policy if exists "Admins manage consultation dashboard" on public.consultation_dashboard_settings;
create policy "Public reads consultation dashboard" on public.consultation_dashboard_settings for select using(true);create policy "Admins manage consultation dashboard" on public.consultation_dashboard_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into public.consultation_dashboard_settings(id) values(1) on conflict(id) do nothing;
